use std::sync::Arc;
use std::sync::atomic::{AtomicUsize, Ordering};
use tracing::{Event, Metadata, Subscriber};
use tracing::span::{Attributes, Id, Record};

struct Capture(Arc<AtomicUsize>);

impl Subscriber for Capture {
    fn enabled(&self, _: &Metadata<'_>) -> bool { true }
    fn new_span(&self, _: &Attributes<'_>) -> Id {
        Id::from_u64(self.0.fetch_add(1, Ordering::SeqCst) as u64 + 1)
    }
    fn record(&self, _: &Id, _: &Record<'_>) {}
    fn record_follows_from(&self, _: &Id, _: &Id) {}
    fn event(&self, _: &Event<'_>) {}
    fn enter(&self, _: &Id) {}
    fn exit(&self, _: &Id) {}
}

fn cold_callsite() {
    let _span = tracing::info_span!("isolated_capture");
}

fn main() {
    let captured = Arc::new(AtomicUsize::new(0));
    let dispatch = tracing::Dispatch::new(Capture(Arc::clone(&captured)));
    std::thread::spawn(cold_callsite).join().expect("plain thread");
    tracing::dispatcher::with_default(&dispatch, cold_callsite);
    let before = captured.load(Ordering::SeqCst);
    assert_eq!(before, 0, "pinned upstream regression must be reproduced");
    let _other_dispatch = tracing::Dispatch::new(tracing::subscriber::NoSubscriber::default());
    tracing::dispatcher::with_default(&dispatch, cold_callsite);
    let after = captured.load(Ordering::SeqCst);
    assert_eq!(after, 1, "the real span must reach the scoped subscriber");
    println!("{{\"pinned_tracing\":\"0.1.44\",\"pinned_core\":\"0.1.36\",\"before_captured\":{before},\"after_captured\":{after},\"status\":\"PASS\"}}");
}
